import SwiftUI struct SignUpView: View { @StateObject private var auth = AuthService.shared @Environment(\.dismiss) private var dismiss @State private var name = "" @State private var email = "" @State private var password = "" @State private var confirm = "" @State private var error: String? = nil @State private var loading = false @State private var showConfirm = false var passwordsMatch: Bool { password == confirm } var isValid: Bool { !name.isEmpty && !email.isEmpty && password.count >= 8 && passwordsMatch } var body: some View { NavigationStack { ScrollView { VStack(spacing: 20) { Image(systemName: "pawprint.fill") .font(.system(size: 56)) .foregroundColor(.blue) .padding(.top, 32) Text("Create Account") .font(.largeTitle.bold()) VStack(spacing: 12) { TextField("Full Name", text: $name) .textFieldStyle(.roundedBorder) .autocapitalization(.words) TextField("Email", text: $email) .textFieldStyle(.roundedBorder) .keyboardType(.emailAddress) .autocapitalization(.none) SecureField("Password (8+ characters)", text: $password) .textFieldStyle(.roundedBorder) SecureField("Confirm Password", text: $confirm) .textFieldStyle(.roundedBorder) if !confirm.isEmpty && !passwordsMatch { Text("Passwords do not match") .font(.caption) .foregroundColor(.red) } } .padding(.horizontal) if let error = error { Text(error) .font(.caption) .foregroundColor(.red) .multilineTextAlignment(.center) .padding(.horizontal) } Button(action: signUp) { if loading { ProgressView() .frame(maxWidth: .infinity) } else { Text("Create Account") .frame(maxWidth: .infinity) } } .buttonStyle(.borderedProminent) .disabled(!isValid || loading) .padding(.horizontal) } } .navigationTitle("Sign Up") .navigationBarTitleDisplayMode(.inline) .toolbar { ToolbarItem(placement: .cancellationAction) { Button("Cancel") { dismiss() } } } .sheet(isPresented: $showConfirm) { ConfirmEmailView(email: email, onConfirmed: { dismiss() }) } } } func signUp() { loading = true error = nil Task { do { try await auth.signUp(name: name, email: email, password: password) showConfirm = true } catch { self.error = error.localizedDescription } loading = false } } }
